import json

def normalize_global_inventory(values, *, windows=True):
 if type(values) is not list: raise ValueError('inventory_not_list')
 if any(type(x) is not int or x < 0 for x in values): raise ValueError('malformed_pid')
 if values.count(0)>1: raise ValueError('duplicate_pid0_sentinel')
 if 0 in values and not windows: raise ValueError('pid0_not_allowed_on_non_windows')
 return sorted(x for x in values if x>0)

def valid_pid0_sentinel(info, *, windows=True):
 return windows and type(info.get('pid')) is int and info.get('pid')==0 and type(info.get('ppid')) is int and info.get('ppid')==0 and type(info.get('create_time')) in (int,float) and type(info.get('create_time')) is not bool and info.get('create_time')==0.0 and info.get('name')=='System Idle Process'
results=[]
assert normalize_global_inventory([0,41001,41002])==[41001,41002];results.append({'case':'Windows inventory PID0 filtered but positive PIDs kept','pass':True})
sentinel={'pid':0,'ppid':0,'create_time':0.0,'name':'System Idle Process'};assert valid_pid0_sentinel(sentinel);results.append({'case':'exact Windows System Idle PID0 row recognized and skipped','pass':True})
for label,bad in [('bool PID',False),('negative PID',-1),('float PID',1.0),('string PID','1')]:
 try: normalize_global_inventory([bad,41001])
 except ValueError: results.append({'case':label+' still rejected','pass':True})
 else: raise AssertionError(label)
for label,bad in [('unexpected PID0 name',dict(sentinel,name='julia.exe')),('unexpected PID0 PPID',dict(sentinel,ppid=1)),('unexpected PID0 creation time',dict(sentinel,create_time=1.0))]:
 assert not valid_pid0_sentinel(bad);results.append({'case':label+' remains fail-closed','pass':True})
print(json.dumps({'schema':'review-only-proposed-pid0-normalization-policy-check-r1','status':'pass','checks':len(results),'results':results},sort_keys=True))

